@sig trait FourEngineConfigurationAssessor_Api {
  def id: Art.BridgeId
  def configuration_evidence_Id : Art.PortId
  def configuration_assessment_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var configuration_assessment: Power_Propulsion_Availability_Supervisor.ConfigurationAssessment.Type = $

  def put_configuration_assessment(value : Power_Propulsion_Availability_Supervisor.ConfigurationAssessment.Type) : Unit = {
    Contract(
      Modifies(configuration_assessment),
      Ensures(
        configuration_assessment == value
      )
    )
    Spec {
      configuration_assessment = value
    }

    Art.putValue(configuration_assessment_Id, Power_Propulsion_Availability_Supervisor.ConfigurationAssessment_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class FourEngineConfigurationAssessor_Initialization_Api (
  val id: Art.BridgeId,
  val configuration_evidence_Id : Art.PortId,
  val configuration_assessment_Id : Art.PortId) extends FourEngineConfigurationAssessor_Api

@datatype class FourEngineConfigurationAssessor_Operational_Api (
  val id: Art.BridgeId,
