  // Logika spec var representing port state for incoming data port
  @spec var configuration_evidence: Power_Propulsion_Availability_Supervisor.ConfigurationEvidence = $

  def get_configuration_evidence() : Option[Power_Propulsion_Availability_Supervisor.ConfigurationEvidence] = {
